def _millis_to_iso(millis: Any) -> str:
    try:
        dt = datetime.fromtimestamp(int(millis) / 1000, tz=timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%S.") + f"{dt.microsecond // 1000:03d}Z"
    except Exception:
        return iso_now()


def find_zcode_db() -> Path:
    return Path(os.environ.get("ZCODE_DB_PATH") or ZCODE_DEFAULT_DB)


def open_zcode_db(db_path: Path):
    conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    conn.row_factory = sqlite3.Row
    return conn


def find_zcode_session(conn, session_id: str, cwd: str | None) -> str | None:
    """Locate the db session id: exact match first, then newest session under cwd."""
    if session_id:
        row = conn.execute("SELECT id FROM session WHERE id=?", (session_id,)).fetchone()
        if row:
            return session_id
    if cwd:
        try:
            resolved = str(Path(cwd).resolve())
        except Exception:
            resolved = cwd
        row = conn.execute(
            "SELECT id FROM session WHERE directory=? ORDER BY time_updated DESC LIMIT 1",
            (resolved,),
        ).fetchone()
        if row:
            return str(row["id"])
    return None


def load_zcode_messages(conn, session_id: str, offset: int) -> list[dict]:
    """Load messages beyond `offset` with their parts, in turn order."""
    messages: list[dict] = []
    rows = conn.execute(
        "SELECT id, data FROM message WHERE session_id=? ORDER BY sequence LIMIT -1 OFFSET ?",
        (session_id, offset),
    ).fetchall()
    for row in rows:
        try:
            data = json.loads(row["data"])
        except (json.JSONDecodeError, TypeError):
            continue
        parts: list[dict] = []
        for prow in conn.execute(
            "SELECT data FROM part WHERE message_id=? ORDER BY sequence", (row["id"],)
        ):
            try:
                parts.append(json.loads(prow["data"]))
            except (json.JSONDecodeError, TypeError):
                continue
        messages.append({"data": data, "parts": parts})
    return messages


def expand_zcode_message(message: dict, parts: list[dict], fallback_ts: str) -> list[dict]:
    """Convert one ZCode db message (+ its parts) to contest events.

    Schema (verified against ~/.zcode/cli/db/db.sqlite):
      - message.data: role, time.created (ms), modelID, tokens.{input,output}
      - part types: text / reasoning / tool / step-start / step-finish / timeline
      - tool parts carry input AND output in one block (state.input / state.output),
        unlike Claude's split tool_use / tool_result pair
    Untyped / internal part types (timeline separators, step markers, ...) are
    dropped silently — the conversational payload lives in text/reasoning/tool.
    """
    role = str(message.get("role") or "").lower()
    if role not in ("user", "assistant", "system", "tool"):
        return []

    time_info = message.get("time") or {}
    created_ms = time_info.get("created")
    ts = _millis_to_iso(created_ms) if created_ms else fallback_ts

    common: dict[str, Any] = {"ts": ts}
    model = message.get("modelID")
    if model:
        common["model"] = model
    tokens = message.get("tokens") or {}
    if isinstance(tokens.get("input"), int):
        common["tokens_in"] = tokens["input"]
    if isinstance(tokens.get("output"), int):
        common["tokens_out"] = tokens["output"]

    out: list[dict] = []
    for part in parts:
        if not isinstance(part, dict):
            continue
        ptype = part.get("type")
        if ptype in (None, *ZCODE_SKIP_PART_TYPES):
            continue
        if ptype == "text":
            text = part.get("text") or ""
            if text:
                out.append({**common, "role": role, "text": text})
        elif ptype == "reasoning":
            thinking = part.get("text") or ""
            if thinking:
                out.append({**common, "role": role, "thinking": thinking})
        elif ptype == "tool":
            state = part.get("state") or {}
            if not isinstance(state, dict):
                state = {}
            out.append({
                **common,
                "role": "tool",
                "tool_name": part.get("tool") or "unknown",
                "tool_call_id": part.get("callID") or f"zcode_{len(out)}",
                "input": state.get("input"),
                "output": state.get("output"),
            })
    return out


def process_zcode_stdin(stdin_data: dict, tool: str, team_id: str) -> int:
    """ZCode Stop hook stdin payload (Claude-compatible, from the zcode agent
    runtime's createClaudeCompatibleHookStdin):
        {
          "session_id": "sess_...", "cwd": "...",
          "hook_event_name": "Stop", "permission_mode": "...",
          "last_assistant_message": "...", "stop_hook_active": false,
          "transcript_path": "<temp file holding the last assistant message only>"
        }
    The temp transcript is not the full conversation, so the source of truth is
    ~/.zcode/cli/db/db.sqlite (session / message / part tables). Env fallbacks
    ZCODE_SESSION_ID / ZCODE_PROJECT_DIR are always injected by the hook runner.
    """
    session_id = (
        stdin_data.get("session_id")
        or stdin_data.get("sessionId")
        or os.environ.get("ZCODE_SESSION_ID")
        or ""
    )
    cwd = (
        stdin_data.get("cwd")
        or os.environ.get("ZCODE_PROJECT_DIR")
        or os.environ.get("CLAUDE_PROJECT_DIR")
        or os.getcwd()
    )
    if not session_id:
        sys.stderr.write("[session-log] missing session_id for zcode hook\n")
        return 1

    repo_root = get_repo_root(cwd) or Path(cwd)
    workspace_root = find_openvela_workspace_root(repo_root)
    if workspace_root is None:
        sys.stderr.write(
            "[session-log] not inside an openvela workspace (no .repo/ found); "
            "collection disabled for this session.\n"
        )
        return 0

    login_result = resolve_github_login(repo_root)
    if not login_result[0]:
        sys.stderr.write(
            "[session-log] FATAL: cannot detect GITHUB_LOGIN. "
            "Set GITHUB_LOGIN env, or run 'gh auth login', or fix git remote URL.\n"
        )
        return 2
    github_login = login_result[0]

    log_root = Path(os.environ.get("SESSION_LOG_DIR")
                    or (Path.home() / ".claude" / "contest-collector-staging"))
    member_dir = log_root / github_login
    try:
        member_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        sys.stderr.write(f"[session-log] cannot create member dir {member_dir}: {e}\n")
        return 1

    db_path = find_zcode_db()
    if not db_path.is_file():
        sys.stderr.write(f"[session-log] skipping: zcode db not found at {db_path}\n")
        return 0
    try:
        conn = open_zcode_db(db_path)
    except sqlite3.Error as e:
        report_error(member_dir, "zcode_db_open", {"tool": tool, "db": str(db_path)}, e)
        return 1

    try:
        db_session_id = find_zcode_session(conn, session_id, cwd)
        if db_session_id is None:
            sys.stderr.write(
                f"[session-log] skipping: no zcode session for id={session_id[:12]} cwd={cwd}\n"
            )
            return 0

        try:
            manifest = read_manifest(member_dir, team_id, github_login, tool)
        except ManifestCorruptError as e:
            sys.stderr.write(f"[session-log] refusing to update corrupt manifest: {e}\n")
            return 1
        entry = next(
            (s for s in manifest.get("sessions", [])
             if s.get("session_id") == db_session_id and s.get("tool") == tool),
            None,
        )
        is_new = entry is None
        watermark = entry.get("raw_event_count", 0) if entry else 0
        start_seq = entry.get("event_count", 0) if entry else 0

        total_rows = conn.execute(
            "SELECT COUNT(*) AS n FROM message WHERE session_id=?", (db_session_id,)
        ).fetchone()["n"]
        if total_rows <= watermark:
            return 0

        messages = load_zcode_messages(conn, db_session_id, watermark)
        fallback_ts = iso_now()
        contest_events: list[dict] = []
        for m in messages:
            contest_events.extend(expand_zcode_message(m["data"], m["parts"], fallback_ts))

        if not contest_events:
            if entry is not None:
                entry["raw_event_count"] = total_rows
                write_manifest(member_dir, manifest, team_id, github_login, tool)
            return 0

        redact_rules = load_redact_rules(member_dir)
        if entry and entry.get("file_path"):
            existing_rel = entry["file_path"].split(f"{github_login}/", 1)[-1] \
                if f"{github_login}/" in entry["file_path"] else None
            jsonl_path = member_dir / existing_rel if existing_rel \
                else member_dir / local_date() / f"{tool}__{db_session_id}.jsonl"
        else:
            jsonl_path = member_dir / local_date() / f"{tool}__{db_session_id}.jsonl"

        try:
            result = append_events(
                jsonl_path, contest_events, db_session_id, team_id, github_login,
                tool, start_seq, redact_rules,
            )
        except Exception as e:
            report_error(member_dir, "jsonl_append", {"tool": tool, "jsonl_path": str(jsonl_path)}, e)
            return 1

        rel_path = f"logs/{github_login}/{jsonl_path.relative_to(member_dir)}"
        if is_new:
            entry = {
                "session_id": db_session_id,
                "tool": tool,
                "started_at": contest_events[0].get("ts") or fallback_ts,
                "last_event_at": iso_now(),
                "event_count": result["written"],
                "raw_event_count": total_rows,
                "file_path": rel_path,
                "collection_mode": "cli",
                "health": "ok",
            }
            last_modeled = next(
                (m["data"].get("modelID") for m in reversed(messages)
                 if m["data"].get("role") == "assistant" and m["data"].get("modelID")),
                None,
            )
            if last_modeled:
                entry["model"] = last_modeled
            manifest.setdefault("sessions", []).append(entry)
        else:
            entry["last_event_at"] = iso_now()
            entry["event_count"] = (entry.get("event_count", 0) or 0) + result["written"]
            entry["raw_event_count"] = total_rows
            entry["file_path"] = rel_path
            if result["redacted"] > 0:
                entry["redacted_count_total"] = entry.get("redacted_count_total", 0) + result["redacted"]

        write_manifest(member_dir, manifest, team_id, github_login, tool)

        auto_export_to_repo(
            repo_root, member_dir, jsonl_path, db_session_id,
            team_id, github_login, tool,
        )

        sys.stderr.write(
            f"[session-log] captured {result['written']} event(s) -> {rel_path}\n"
        )
        return 0
    finally:
        try:
            conn.close()
        except Exception:
            pass


