def _zcode_session_to_events(conn, session_id, team_id, github_login, tool):
    """Richer extractor for ZCode db (session/message/part tables): emits text,
    reasoning and tool events. Tool parts carry input AND output in one block."""
    messages = conn.execute(
        "SELECT id, time_created, data FROM message WHERE session_id=? ORDER BY sequence",
        (session_id,),
    ).fetchall()
    if not messages:
        return []
    events = []
    seq = 0
    for msg in messages:
        try:
            mdata = json.loads(msg["data"])
        except Exception:
            continue
        role = mdata.get("role", "user")
        if role not in ("user", "assistant", "system", "tool"):
            continue
        ts = _millis_to_iso(mdata.get("time", {}).get("created") or msg["time_created"])
        model = mdata.get("modelID")
        tokens = mdata.get("tokens") or {}
        common = {"ts": ts}
        if model:
            common["model"] = model
        if isinstance(tokens.get("input"), int):
            common["tokens_in"] = tokens["input"]
        if isinstance(tokens.get("output"), int):
            common["tokens_out"] = tokens["output"]
        parts = conn.execute(
            "SELECT data FROM part WHERE message_id=? ORDER BY sequence",
            (msg["id"],),
        ).fetchall()
        for p in parts:
            try:
                pdata = json.loads(p["data"])
            except Exception:
                continue
            ptype = pdata.get("type")
            if ptype not in ("text", "reasoning", "tool"):
                continue
            if ptype == "text":
                text = (pdata.get("text") or "").strip()
                if not text:
                    continue
                ev = {**common, "role": role, "text": pdata["text"]}
            elif ptype == "reasoning":
                thinking = (pdata.get("text") or "").strip()
                if not thinking:
                    continue
                ev = {**common, "role": role, "thinking": pdata["text"]}
            else:
                state = pdata.get("state") or {}
                if not isinstance(state, dict):
                    state = {}
                ev = {
                    **common,
                    "role": "tool",
                    "tool_name": pdata.get("tool") or "unknown",
                    "tool_call_id": pdata.get("callID") or f"zcode_{seq}",
                    "input": state.get("input"),
                    "output": state.get("output"),
                }
            events.append({
                "schema_version": "1.0", "session_id": session_id,
                "team_id": team_id, "github_login": github_login,
                "tool": tool, "seq": seq, **ev,
            })
            seq += 1
    return events


